  "anomalies": [
    {
      "category": "open_connection",
      "components": ["HSE2", "HSE3", "FCC2", "NAVC2"],
      "pins": ["HSE2.1", "HSE2.3", "FCC2.5", "FCC2.37", "HSE3.1", "HSE3.3", "NAVC2.11", "NAVC2.24", "FCC2.12", "FCC2.13", "NAVC2.5", "NAVC2.6"],
      "nets": ["NET0104", "NET0062", "NET0125", "NET0176"],
      "observed": "The 25 MHz crystals are connected to MCU GPIO pins rather than the HSE oscillator pins: HSE2 nets NET0104/NET0062 connect to FCC2 PE6/PE7 (pins 5/37), and HSE3 nets NET0125/NET0176 connect to NAVC2 PC3/PC4 (pins 11/24). The HSE pins PH0/PH1 are not connected to these crystals.",
      "expected": "Each crystal should connect to its MCU's HSE oscillator input/output pins PH0/PH1, as required for the specified external high-speed clock.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "HSE2 25MHz; NET0104 and NET0062 are also shown at FCC2 PE6 (pin 5) and PE7 (pin 37). Sheet FCC, PDF page 2/6."
        },
        {
          "source": "schematic",
          "quote": "HSE3 25MHz; NET0125 and NET0176 are also shown at NAVC2 PC3 (pin 11) and PC4 (pin 24). Sheet NAVC, PDF page 3/6."
        },
        {
          "source": "spec",
          "quote": "HSE crystal (both MCUs) | ABM8G-25.000MHZ-4Y-T3"
        }
      ],
      "impact": "Neither MCU can use its external 25 MHz crystal as drawn. Firmware configured for the external HSE clock may fail to start or run using a different, less accurate internal clock source.",
      "confidence": 0.99
    }
  ],
  "summary": "Both MCU crystals are routed to GPIO pins instead of the HSE oscillator pins. This prevents the specified external clock sources from functioning as intended."
}

